//! Cargo-driven `dbghelp.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x79640000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff98000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff98000000u64)),
        o => panic!("dbghelp-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:pseh", "engine:oldnames", "import:version", "import:psapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        "x86_64" => &["engine:wine", "engine:pseh", "engine:oldnames", "import:version", "import:psapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "aarch64" => &["engine:wine", "engine:pseh", "engine:oldnames", "import:version", "import:psapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/dbghelp",
        "dll/win32/dbghelp",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "HAVE_ALLOCA_H",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRT_NON_CONFORMING_SWPRINTFS",
        "_DLL",
        "_IMAGEHLP_SOURCE_",
        "_WIN32_WINNT=0x502",
        "_WINE",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("dbghelp_shims", &["dll/win32/dbghelp/coff.c", "dll/win32/dbghelp/cpu_arm.c", "dll/win32/dbghelp/cpu_arm64.c", "dll/win32/dbghelp/cpu_i386.c", "dll/win32/dbghelp/cpu_x86_64.c", "dll/win32/dbghelp/dbghelp.c", "dll/win32/dbghelp/dwarf.c", "dll/win32/dbghelp/image.c", "dll/win32/dbghelp/inflate.c", "dll/win32/dbghelp/minidump.c", "dll/win32/dbghelp/module.c", "dll/win32/dbghelp/msc.c", "dll/win32/dbghelp/path.c", "dll/win32/dbghelp/pe_module.c", "dll/win32/dbghelp/rosstubs.c", "dll/win32/dbghelp/rsym.c", "dll/win32/dbghelp/source.c", "dll/win32/dbghelp/stabs.c", "dll/win32/dbghelp/stack.c", "dll/win32/dbghelp/storage.c", "dll/win32/dbghelp/symbol.c", "dll/win32/dbghelp/type.c"])
        .whole_c_objects("dbghelp_shims")
        .rc("dll/win32/dbghelp/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/dbghelp/dbghelp.spec", "dbghelp.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("dll/win32/psapi/psapi.spec", "psapi.dll", "psapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
